<?php
if (!defined('ABSPATH')) exit;
get_header();
?>
<main class="iw-library-page iw-people-page">
<?php while (have_posts()) : the_post(); $id=get_the_ID(); $lead=interworld_knowledge_value('iw_person_lead',$id); $period=interworld_knowledge_value('iw_person_period',$id); $facts=interworld_knowledge_value('iw_person_facts',$id); $aliases=interworld_knowledge_value('iw_person_aliases',$id); $roles=get_the_terms($id,'person_category'); ?>
  <section class="iw-book-detail-hero"><div class="iw-library-wrap"><div class="iw-library-breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">Главная</a> / <a href="<?php echo esc_url(get_post_type_archive_link('person')); ?>">Личности</a> / <?php the_title(); ?></div><div class="iw-person-hero"><div class="iw-person-portrait"><?php if (has_post_thumbnail()) the_post_thumbnail('large',array('alt'=>'')); else echo '<span aria-hidden="true">✦</span>'; ?></div><div><div class="iw-library-eyebrow">ЛИЧНОСТИ МЕЖМИРЬЯ</div><h1><?php the_title(); ?></h1><?php if ($lead) : ?><p class="iw-person-lead"><?php echo esc_html($lead); ?></p><?php endif; ?><?php if ($period) : ?><p class="iw-person-period"><?php echo esc_html($period); ?></p><?php endif; ?><?php if ($roles && !is_wp_error($roles)) : ?><div class="iw-book-tags"><?php foreach ($roles as $role) : $url=get_term_link($role); if (!is_wp_error($url)) : ?><a href="<?php echo esc_url($url); ?>"><?php echo esc_html($role->name); ?></a><?php endif; endforeach; ?></div><?php endif; ?></div></div></div></section>
  <?php if ($aliases || $facts) : ?><section class="iw-library-section iw-library-wrap"><h2>Кратко о личности</h2><?php if ($aliases) : ?><p>Другие имена: <?php echo esc_html(implode(', ',array_filter(array_map('trim',preg_split('/\R/u',(string)$aliases))))); ?></p><?php endif; ?><?php if ($facts) : ?><ul class="iw-person-facts"><?php foreach (array_filter(array_map('trim',preg_split('/\R/u',(string)$facts))) as $fact) : ?><li><?php echo esc_html($fact); ?></li><?php endforeach; ?></ul><?php endif; ?></section><?php endif; ?>
  <?php if (trim(wp_strip_all_tags(get_the_content()))) : ?><section class="iw-library-section iw-library-wrap iw-book-content"><h2>Биография и контекст</h2><?php the_content(); ?></section><?php endif; ?>
  <?php foreach (array('iw_person_authored_books'=>'Книги автора','iw_person_about_books'=>'Книги о личности') as $field=>$heading) : $books=interworld_knowledge_ids($field,$id); if ($field==='iw_person_authored_books') $books=array_unique(array_merge($books,array_map('absint',(array)get_post_meta($id,'_iw_person_authored_book_ids',true)))); $books=array_filter($books,function($book){return get_post_type($book)==='library_book' && get_post_status($book)==='publish';}); if (!$books) continue; ?><section class="iw-library-section iw-library-wrap"><h2><?php echo esc_html($heading); ?></h2><div class="iw-book-grid"><?php foreach ($books as $book) echo interworld_library_book_card($book); ?></div></section><?php endforeach; ?>
  <?php interworld_knowledge_relations($id); interworld_knowledge_sources($id); interworld_knowledge_continue($id, array(get_post_type_archive_link('person')=>'Личности')); ?>
<?php endwhile; ?>
</main>
<?php get_footer(); ?>
